1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	/**
57	 * Both roundings go the MHPCO's way, and both are applied once, at the very end
58	 * of a calculation — never to an intermediate amount. The two are stated here as
59	 * a pair because that is the rule: it is one policy with two directions, and
60	 * which direction applies follows from who pays.
61	 */
62	const roundedUpForWhatTheCustomerPays = Math.ceil;
63	const roundedDownForWhatTheMHPCOPays = Math.floor;
64	
65	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
66	const CURSE_SURCHARGE_PERCENT = 50;
67	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
68	/**
69	 * Enchantment is read by two unrelated rules with different cut-offs: this one
70	 * charges a premium surcharge from 5 up, and REDUCED_REIMBURSEMENT_THRESHOLD
71	 * halves a claim from 8 up. Each threshold is named after the rule it gates so
72	 * the two cannot be mistaken for one shared notion of "highly enchanted".
73	 */
74	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
75	const LOYALTY_DISCOUNT_PERCENT = 20;
76	const LOYALTY_THRESHOLD_YEARS = 2;
77	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
78	
79	/**
80	 * Everything the pricing rules need to know about an item type lives here, so
81	 * that "what is a rune?" has a single answer. Components are the small parts
82	 * (runes, moonstones) that can be bought as a building block; main items
83	 * (swords, amulets, ...) never form a block.
84	 */
85	const ITEM_TYPES: Record<
86	  string,
87	  { unitPremium: number; insuranceValue: number; isComponent: boolean }
88	> = {
89	  sword: { unitPremium: 100, insuranceValue: 1000, isComponent: false },
90	  amulet: { unitPremium: 60, insuranceValue: 600, isComponent: false },
91	  staff: { unitPremium: 80, insuranceValue: 800, isComponent: false },
92	  potion: { unitPremium: 40, insuranceValue: 400, isComponent: false },
93	  rune: { unitPremium: 25, insuranceValue: 250, isComponent: true },
94	  moonstone: { unitPremium: 25, insuranceValue: 250, isComponent: true },
95	};
96	
97	/**
98	 * The single gate onto ITEM_TYPES, so that an item the MHPCO does not insure is
99	 * refused by name rather than surfacing as a stray TypeError somewhere downstream.
100	 */
101	const itemTypeOf = (type: string): (typeof ITEM_TYPES)[string] => {
102	  const itemType = ITEM_TYPES[type];
103	  if (itemType === undefined) {
104	    throw new Error(`unknown item type: ${type}`);
105	  }
106	  return itemType;
107	};
108	
109	/** A building block of 3 alike components is offered at this base premium. */
110	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
111	const COMPONENT_BLOCK_SIZE = 3;
112	
113	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
114	const countByType = (items: Item[]): [string, number][] => {
115	  const counts = new Map<string, number>();
116	  for (const item of items) {
117	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
118	  }
119	  return [...counts];
120	};
121	
122	/**
123	 * Prices every item of one type together, because exactly 3 alike components
124	 * form a block charged as one. "Alike" means the same type, and the block does
125	 * not repeat: 4 or 7 runes are each priced per item.
126	 */
127	const basePremiumForType = (type: string, count: number): number => {
128	  const { unitPremium, isComponent } = itemTypeOf(type);
129	  return isComponent && count === COMPONENT_BLOCK_SIZE
130	    ? COMPONENT_BLOCK_BASE_PREMIUM
131	    : count * unitPremium;
132	};
133	
134	const sumOfBasePremiums = (items: Item[]): number =>
135	  countByType(items).reduce(
136	    (sum, [type, count]) => sum + basePremiumForType(type, count),
137	    0,
138	  );
139	
140	/**
141	 * A rule whose rate is ADDED to those of every other matching rule. Read with
142	 * filter+reduce: matching several rules charges for each.
143	 *
144	 * Distinct from ExclusiveRule<T> below, which has the same {appliesTo, rate}
145	 * shape but the opposite semantics. The two are separate named types rather
146	 * than one shared shape so that the reader — and the compiler — cannot mistake
147	 * a stacking table for a first-match-wins one.
148	 */
149	interface StackingRule<T> {
150	  appliesTo: (subject: T) => boolean;
151	  rate: number;
152	}
153	
154	/**
155	 * What a stacking table charges against a base amount: every matching rule
156	 * contributes, so the rates add up rather than compete. This is the one place
157	 * the filter+reduce reading of StackingRule is performed — item surcharges and
158	 * policy adjustments are both this same idea, differing only in which table
159	 * they consult and what their percentages are taken of.
160	 */
161	const sumOfMatchingRates = <T>(
162	  rules: StackingRule<T>[],
163	  subject: T,
164	  base: number,
165	): number =>
166	  rules
167	    .filter(({ appliesTo }) => appliesTo(subject))
168	    .reduce((sum, { rate }) => sum + percent(base, rate), 0);
169	
170	/**
171	 * A rule that is an ALTERNATIVE to the others: the first match wins and the
172	 * rest are skipped. Read with find. Order is therefore meaningful — it encodes
173	 * precedence, and reordering the table changes results.
174	 */
175	interface ExclusiveRule<T> {
176	  appliesTo: (subject: T) => boolean;
177	  rate: number;
178	}
179	
180	/**
181	 * Item-specific modifiers: each applies to one item and is charged as a
182	 * percentage of THAT item's unit premium, never of the policy total.
183	 * They stack — an item matching several rules is charged for each.
184	 *
185	 * Unit premium, not the item's share of the policy base: the two differ only
186	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
187	 * no test pins down a surcharged component yet. Revisit when one does.
188	 */
189	const ITEM_MODIFIERS: StackingRule<Item>[] = [
190	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
191	  {
192	    appliesTo: (item) =>
193	      (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD,
194	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
195	  },
196	];
197	
198	const surchargeForItem = (item: Item): number =>
199	  sumOfMatchingRates(ITEM_MODIFIERS, item, itemTypeOf(item.type).unitPremium);
200	
201	const sumOfItemSurcharges = (items: Item[]): number =>
202	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
203	
204	/**
205	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
206	 * premium (the sum of item base premiums, before any item surcharge), so no
207	 * modifier is ever computed on top of another. Discounts carry a negative rate.
208	 */
209	interface PolicyContext {
210	  customer: Customer;
211	  /** Quotes already issued to this customer earlier in the scenario. */
212	  previousContracts: number;
213	}
214	
215	const POLICY_MODIFIERS: StackingRule<PolicyContext>[] = [
216	  // Always applies: every item in a quote is treated as a first insurance,
217	  // regardless of how long the customer has been with the MHPCO.
218	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
219	  {
220	    // Negative rate: a discount is just a surcharge pointing the other way, so
221	    // it needs no separate code path and cannot stack onto another modifier.
222	    appliesTo: ({ customer }) =>
223	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
224	    rate: -LOYALTY_DISCOUNT_PERCENT,
225	  },
226	  {
227	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
228	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
229	  },
230	];
231	
232	const sumOfPolicyAdjustments = (
233	  context: PolicyContext,
234	  policyBasePremium: number,
235	): number =>
236	  sumOfMatchingRates(POLICY_MODIFIERS, context, policyBasePremium);
237	
238	const premiumFor = (context: PolicyContext, items: Item[]): number => {
239	  const policyBasePremium = sumOfBasePremiums(items);
240	  return roundedUpForWhatTheCustomerPays(
241	    policyBasePremium +
242	      sumOfItemSurcharges(items) +
243	      sumOfPolicyAdjustments(context, policyBasePremium) +
244	      PROCESSING_FEE,
245	  );
246	};
247	
248	/** A policy created by a quote step, tracked so later claims can draw on it. */
249	interface Policy {
250	  items: Item[];
251	  remainingCap: number;
252	}
253	
254	const DEDUCTIBLE_PER_DAMAGE = 100;
255	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
256	
257	const insuranceSumOf = (items: Item[]): number =>
258	  items.reduce((sum, item) => sum + itemTypeOf(item.type).insuranceValue, 0);
259	
260	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
261	const REDUCED_REIMBURSEMENT_PERCENT = 50;
262	
263	/** Reimbursed in full when no clause below claims the item. */
264	const FULL_REIMBURSEMENT_PERCENT = 100;
265	const DRAGON_MATERIAL = "dragon";
266	
267	/**
268	 * Clauses that change how much of a damage is reimbursed. Exclusive and ordered
269	 * by precedence, because clauses overlap (a highly enchanted dragon-material
270	 * item matches more than one) and they are alternatives — unlike the stacking
271	 * ITEM_MODIFIERS, which the {appliesTo, rate} shape would otherwise suggest.
272	 */
273	const REIMBURSEMENT_CLAUSES: ExclusiveRule<Item>[] = [
274	  {
275	    appliesTo: (item) =>
276	      (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD,
277	    rate: REDUCED_REIMBURSEMENT_PERCENT,
278	  },
279	  // Listed after the clause above so that a highly enchanted dragon item is
280	  // still reimbursed at 50 %. This entry yields exactly what the no-clause
281	  // default yields, so removing it would not change any current result — it is
282	  // here because the spec states dragon material as a rule, and because the
283	  // ordering is what makes the 50 % rule win.
284	  {
285	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
286	    rate: FULL_REIMBURSEMENT_PERCENT,
287	  },
288	];
289	
290	const reimbursementRateFor = (item: Item): number =>
291	  REIMBURSEMENT_CLAUSES.find(({ appliesTo }) => appliesTo(item))?.rate ??
292	  FULL_REIMBURSEMENT_PERCENT;
293	
294	/**
295	 * Which insured item a damage entry is about. The counterpart to itemTypeOf:
296	 * both resolve a name to the thing it denotes, and both are the one place their
297	 * lookup happens — so the "not covered by the policy" and "more damage entries
298	 * than insured" rules have a single site to be enforced from.
299	 *
300	 * An item the policy does not cover is refused here, which also covers a damage
301	 * naming a type the MHPCO does not insure at all: neither is in the policy.
302	 */
303	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item => {
304	  const insuredItem = insuredItems.find(
305	    (item) => item.type === damage.itemType,
306	  );
307	  if (insuredItem === undefined) {
308	    throw new Error(
309	      `damaged item is not covered by the policy: ${damage.itemType}`,
310	    );
311	  }
312	  return insuredItem;
313	};
314	
315	/**
316	 * The clause is applied to the damage first; the deductible comes off whatever
317	 * the clause leaves.
318	 *
319	 * Takes the already-resolved item, so this is pure arithmetic over a damage and
320	 * the item it hit — mirroring basePremiumForType, which likewise prices an
321	 * already-resolved type rather than doing its own lookup.
322	 */
323	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
324	  percent(damage.amount, reimbursementRateFor(damagedItem)) -
325	  DEDUCTIBLE_PER_DAMAGE;
326	
327	/**
328	 * The contract a quote step issues: what it covers, and how much of its cap is
329	 * still available to later claims.
330	 */
331	const policyFor = (items: Item[]): Policy => ({
332	  items,
333	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
334	});
335	
336	/**
337	 * What an incident is worth against a policy, as a pure calculation: each
338	 * damage is settled on its own (own clause, own deductible) and the results are
339	 * added up. Drawing this down from the policy's cap is the caller's job.
340	 */
341	const payoutForIncident = (
342	  incident: ClaimStep["incident"],
343	  insuredItems: Item[],
344	): number =>
345	  incident.damages.reduce(
346	    (sum, damage) =>
347	      sum + payoutForDamage(damage, insuredItemFor(damage, insuredItems)),
348	    0,
349	  );
350	
351	/**
352	 * Settles an incident against a policy and draws the payout down from its cap.
353	 * Mutates the policy, because what this claim consumes has to be visible to
354	 * every later claim on the same one.
355	 *
356	 * The cap is a ceiling, not just a running total: once it is exhausted a claim
357	 * is paid only what is left of it. Rounding happens once, here, after the clamp
358	 * — so per-damage amounts stay fractional (a multi-item incident is not rounded
359	 * once per damage) and the cap stays whole.
360	 */
361	/**
362	 * A policy covering one sword cannot answer for two damaged swords. Checked
363	 * before anything is paid, because the whole claim is rejected rather than
364	 * settled as far as the cover reaches.
365	 */
366	const assertDamagesAreCovered = (
367	  damages: Damage[],
368	  insuredItems: Item[],
369	): void => {
370	  const insuredCounts = new Map(countByType(insuredItems));
371	  for (const [itemType, damaged] of countByType(
372	    damages.map((damage) => ({ type: damage.itemType })),
373	  )) {
374	    const insured = insuredCounts.get(itemType) ?? 0;
375	    if (insured === 0) {
376	      throw new Error(`damaged item is not covered by the policy: ${itemType}`);
377	    }
378	    if (damaged > insured) {
379	      throw new Error(`more ${itemType} damages than the policy covers`);
380	    }
381	  }
382	};
383	
384	const settleClaim = (
385	  policy: Policy,
386	  incident: ClaimStep["incident"],
387	): StepResult => {
388	  assertDamagesAreCovered(incident.damages, policy.items);
389	  const payout = roundedDownForWhatTheMHPCOPays(
390	    Math.min(payoutForIncident(incident, policy.items), policy.remainingCap),
391	  );
392	  policy.remainingCap -= payout;
393	  return { payout, remainingCap: policy.remainingCap };
394	};
395	
396	/**
397	 * Steps are executed in order because a step's result can depend on the ones
398	 * before it: the count of contracts already issued decides the follow-up
399	 * discount, and the policies a quote registers are what later claims draw on.
400	 */
401	export const runScenario = (scenario: Scenario): ScenarioResult => {
402	  let previousContracts = 0;
403	  const policies = new Map<number, Policy>();
404	
405	  const results = scenario.steps.map((step, index): StepResult => {
406	    if (step.op === "claim") {
407	      // Unguarded: no test yet describes a claim naming a policy that was never
408	      // quoted. The "claim references an item/policy not in the policy" test
409	      // will force this honest.
410	      const policy = policies.get(step.policy) as Policy;
411	      return settleClaim(policy, step.incident);
412	    }
413	
414	    const premium = premiumFor(
415	      { customer: scenario.customer, previousContracts },
416	      step.items,
417	    );
418	    policies.set(index, policyFor(step.items));
419	    // Counted after pricing, so a quote never discounts itself, and only for
420	    // quotes, because a claim does not issue a contract.
421	    previousContracts += 1;
422	    return { premium };
423	  });
424	  return { results };
425	};
