/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
const countByType = (items: Item[]): [string, number][] => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return [...counts];
};

