 * An item the policy does not cover is refused here, which also covers a damage
 * naming a type the MHPCO does not insure at all: neither is in the policy.
 */
const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item => {
  const insuredItem = insuredItems.find(
    (item) => item.type === damage.itemType,
  );
  if (insuredItem === undefined) {
    throw new Error(
      `damaged item is not covered by the policy: ${damage.itemType}`,
    );
  }
  return insuredItem;
};

